CREATE TABLE IF NOT EXISTS sentence_drills (
  id TEXT PRIMARY KEY,
  sentence_id TEXT NOT NULL,
  exam_point TEXT NOT NULL,
  kind TEXT NOT NULL,
  prompt TEXT NOT NULL,
  answer TEXT NOT NULL,
  hint TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_drills_point ON sentence_drills(exam_point);
DELETE FROM sentence_drills;
